/* 第04轮导演输入与可暂停规划；真实示例媒体不代表模型生成。 */
window.createCimoraDirectionModel=function(M,S){
 const P=M.production,clone=M.clone,loaded=new Set();
 const profiles={'local-demo':{name:'原创测试片 / 本地流程演示',purposes:['identity','scene','composition','firstFrame','lastFrame','action'],audio:false,multi:true,notice:'仅声明本地输入规划能力，不代表任何供应商API；测试片不随提示词生成。'},'basic-demo':{name:'基础单参考配置演示',purposes:['scene','composition'],audio:false,multi:false,notice:'此配置不支持首尾帧、多参考与音频；请改为文字描述或切换本地规划演示。'}};
 const purposes={identity:'角色身份',scene:'场景',composition:'构图',firstFrame:'首帧',lastFrame:'尾帧',action:'动作'};
 const media=(variant=0,group=false)=>({url:group?'assets/direction-group.mp4':variant%2?'assets/direction-b.mp4':'assets/direction-a.mp4',in:0,out:group?12:4,source:'Cimora原创程序绘制连续动作测试片',usage:'用于真实播放器/候选/片段体验，非模型生成，不评价生成质量',silent:true});
 function ensure(c){const list=P.shots(c.e);for(const s of list){if(!s.direction){const lines=s.sources?.flatMap(r=>(r.snapshot.comicSource?.textBlocks||[]).map(t=>({...clone(t),speaker:t.speakerName||'未指定'})))||[];s.direction={startProp:'',endProp:'',startPose:'',endPose:'',performance:'',framing:'中景',camera:'固定',profile:'local-demo',audio:false,locked:false,references:[],lines:lines.length?lines:s.dialogue?[{id:S.id('line'),originalText:s.dialogue,text:s.dialogue,speaker:'未指定',type:'dialogue'}]:[],preparation:null};}}const key=c.p.id+'/'+c.c.id;if(!loaded.has(key)){loaded.add(key);if(c.e.directionJob?.status==='running'){c.e.directionJob.status='paused';c.e.directionJob.notice='刷新后已暂停，手动继续才启动后续组';M.save();}}return list;}
 const shot=(c,id)=>ensure(c).find(s=>s.id===id),active=c=>['running','paused'].includes(c.e.directionJob?.status),blocked=c=>active(c)?'请先完成或停止导演批次':c.e.run&&['running','paused'].includes(c.e.run.status)?'请先停止已有制作批次':null;
 function edit(c,id,v){if(blocked(c))return blocked(c);const s=shot(c,id);if(!s)return '镜头不存在';if(s.direction.locked)return '镜头已锁定，请先解锁';const profile=v.profile||s.direction.profile;if(!profiles[profile])return '未知能力配置';if(v.audio&&!profiles[profile].audio)return '此配置不支持音频';if(s.direction.references.some(r=>!profiles[profile].purposes.includes(r.purpose))||!profiles[profile].multi&&s.direction.references.length>1)return '此配置不支持现有参考用途或数量，请先清除不兼容参考';for(const k of ['intent','duration'])if(k in v)s[k]=k==='duration'?Math.max(4,Math.min(12,Number(v[k])||4)):String(v[k]);for(const k of ['startProp','endProp','startPose','endPose','performance','framing','camera','profile'])if(k in v)s.direction[k]=String(v[k]);if('audio'in v)s.direction.audio=!!v.audio;if(v.lines){s.direction.lines=v.lines.map(t=>{const old=s.direction.lines.find(x=>x.id===t.id);return {...clone(t),originalText:old?.originalText??t.originalText??t.text};});s.dialogue=s.direction.lines.filter(t=>!t.type||t.type==='dialogue').map(t=>(t.speaker||'未指定')+'：'+t.text).join('\n');}s.version++;c.e.reviewChecks=[false,false,false];M.save();return null;}
 function references(c,id,refs){if(blocked(c))return blocked(c);const s=shot(c,id),cfg=profiles[s.direction.profile];if(s.direction.locked)return '镜头已锁定';if(!cfg.multi&&refs.length>1)return '此配置不支持多个参考';if(refs.some(r=>!cfg.purposes.includes(r.purpose)))return '此配置不支持所选参考用途';const out=[];for(const r of refs){if(r.kind==='asset'){const a=S.state.assets.find(a=>a.id===r.id&&a.projectId===c.p.id);if(!a)return '参考资产不属于当前项目';out.push({...r,version:a.version,snapshot:clone(a)});}else{const src=s.sources?.[r.sourceIndex];if(!src)return '漫画来源不存在';out.push({...r,version:src.version,snapshot:clone(src.snapshot)});}}s.direction.references=out;s.version++;M.save();return null;}
 function prepare(c,id,v){if(blocked(c))return blocked(c);const s=shot(c,id);if(s.direction.locked)return '镜头已锁定';s.direction.preparation={ratio:['16:9','9:16','1:1'].includes(v.ratio)?v.ratio:'16:9',status:'pending',repair:!!v.repair,extend:!!v.extend,originalParts:clone(s.sources?.flatMap(r=>r.snapshot.comicSource?.importSource?.parts||[])||[]),notice:'仅登记目标比例准备，含字原图保留；修复/补画未实际执行，不是无字首帧。'};s.version++;M.save();return null;}
 function continuity(c){const ss=ensure(c),out=[];for(let i=1;i<ss.length;i++){const a=ss[i-1],b=ss[i];for(const [field,key]of [['prop','Prop'],['pose','Pose']]){const before=a.direction['end'+key],after=b.direction['start'+key];if(before&&after&&before!==after)out.push({from:a.id,to:b.id,field,before,after,basis:'人工结构化状态逐字比较，非AI视觉理解'});}}return out;}
 function snapshot(c,s){return clone({intent:s.intent,dialogue:s.dialogue,duration:s.duration,shotVersion:s.version,sources:s.sources||[],direction:s.direction,bindings:{},soundPolicy:'silent',musicPolicy:'none'});}
 function make(c,s,input,options={}){const failed=options.fail,old=s.candidates.length;const candidate={id:S.id('direct-clip'),version:old+1,status:failed?'failed':'ready',mode:'direction-demo',createdAt:new Date().toISOString(),model:input.direction.profile,instruction:options.instruction||'',input:clone(input),cost:failed?0:.4,prototype:true,media:failed?null:clone(options.media||media(old)),groupId:options.groupId||null,warning:'原创固定测试片，非模型生成；输入保存用于流程验证，视频不随指令变化。'};s.candidates.unshift(candidate);if(!failed)c.e.spent=Math.round((c.e.spent+.4)*100)/100;c.e.reviewChecks=[false,false,false];return candidate;}
 function generate(c,id,v={}){if(blocked(c))return {error:blocked(c)};const s=shot(c,id);if(!s)return {error:'镜头不存在'};if(s.direction.locked)return {error:'镜头已锁定'};if(!v.fail&&c.e.spent+.4>c.e.budget+1e-9)return {error:'剩余预算不足（模拟）'};const candidate=make(c,s,snapshot(c,s),v);M.save();return {candidate};}
 function adopt(c,id,cid,automatic=false){const s=shot(c,id),item=s?.candidates.find(v=>v.id===cid);const confirmingCurrent=s?.adoptedId===cid&&s.direction.adoption?.mode==='automatic-review';if(blocked(c)&&!automatic&&!confirmingCurrent)return blocked(c);if(s?.direction.locked)return '镜头已锁定，不能覆盖采用';if(!item||item.status!=='ready')return '候选不可采用';s.adoptedId=cid;s.direction.adoption={candidateId:cid,mode:automatic?'automatic-review':'manual',label:automatic?'自动选用，待审阅':'人工显式采用',at:new Date().toISOString()};c.e.reviewChecks=[false,false,false];M.save();return null;}
 function lock(c,id,value){if(blocked(c))return blocked(c);const s=shot(c,id);s.direction.locked=!!value;M.save();return null;}
 function plan(c,ids,v={}){const selected=ensure(c).filter(s=>ids.includes(s.id)&&!s.direction.locked&&(!v.auto||!s.adoptedId));const size=Math.max(1,Math.min(3,Number(v.groupSize)||1)),groups=[];for(let i=0;i<selected.length;i+=size){const items=selected.slice(i,i+size);if(items.length>1&&items.some(s=>!profiles[s.direction.profile].multi))return {error:'所选能力配置不支持多镜组合规划'};groups.push({id:S.id('group'),status:'queued',shots:items.map(s=>({id:s.id,version:s.version,input:snapshot(c,s)})),fail:items.some(s=>v.failIds?.includes(s.id)),callCount:0});}return {id:S.id('direction-job'),status:'planned',groups,auto:!!v.auto,skipped:ids.filter(id=>!selected.some(s=>s.id===id)),cost:Math.round(selected.length*.4*100)/100,notice:'本机模拟规划；一组可组织多个镜头，不代表实际供应商调用。'};}
 function start(c,job){if(job.error)return job.error;if(blocked(c))return blocked(c);if(!job.groups.length)return '没有可启动的镜头（锁定或已有采用已跳过）';for(const g of job.groups)for(const r of g.shots){const s=shot(c,r.id);if(!s||s.version!==r.version||s.direction.locked)return '计划后镜头输入或锁定状态有变化，请重新规划';}if(c.e.spent+job.cost>c.e.budget+1e-9)return '剩余预算不足（模拟），整批未启动';job.status='running';c.e.directionJob=job;M.save();return null;}
 function advance(c){const job=c.e.directionJob;if(job?.status!=='running')return;const g=job.groups.find(g=>g.status==='queued');if(!g){job.status='complete';M.save();return;}g.callCount++;const groupMedia=media(g.shots[0].input.shotVersion,g.shots.length>1);for(let i=0;i<g.shots.length;i++){const r=g.shots[i],s=shot(c,r.id);if(!s||s.direction.locked){g.status='skipped';continue;}const candidate=make(c,s,r.input,{fail:g.fail,groupId:g.id,media:{...groupMedia,...(g.shots.length>1?{playbackUrl:'assets/direction-group-'+(i+1)+'.mp4'}:{}),in:g.shots.length>1?i*4:0,out:g.shots.length>1?(i+1)*4:4}});if(job.auto&&!s.adoptedId&&!g.fail)adopt(c,s.id,candidate.id,true);}g.status=g.status==='skipped'?'skipped':g.fail?'failed':'ready';if(!job.groups.some(g=>g.status==='queued'))job.status='complete';M.save();return g;}
 function pause(c){if(c.e.directionJob?.status==='running'){c.e.directionJob.status='paused';M.save();}}
 function resume(c){if(c.e.directionJob?.status==='paused'){c.e.directionJob.status='running';M.save();}}
 function stop(c){if(active(c)){c.e.directionJob.status='stopped';M.save();}}
 function retry(c,ids){const last=c.e.directionJob;const failed=last?.groups.filter(g=>g.status==='failed').flatMap(g=>g.shots.map(r=>r.id))||[];return plan(c,ids.filter(id=>failed.includes(id)));}
 const legacyGenerate=P.generate,legacyAdopt=P.adopt;P.generate=(c,id,...args)=>{const s=shot(c,id);return s?.direction.locked?{error:'镜头已锁定'}:blocked(c)?{error:blocked(c)}:legacyGenerate(c,id,...args);};P.adopt=(c,id,...args)=>{const s=shot(c,id);return s?.direction.locked?'镜头已锁定':blocked(c)||legacyAdopt(c,id,...args);};
 M.direction={ensure,shot,edit,references,prepare,continuity,generate,adopt,lock,plan,start,advance,pause,resume,stop,retry,profiles,purposes,media,blocked};return M;
};




